import React from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import LoginForm from '../components/login/LoginForm';
import SignupVisual from '../components/signup/SignupVisual';


const Login = () => {
    return (
        <div className="bg-background text-on-background min-h-screen flex flex-col">
            <Header />

            {/* Main Content */}
            <main className="flex-grow flex items-center justify-center pt-24 pb-12 ml-28 mr-28 ">
                <div className="max-w-[1100px] w-full grid grid-cols-2 bg-surface-container-lowest rounded-lg border border-outline-variant overflow-hidden shadow-[0px_4px_6px_rgba(0,0,0,0.05)]">
                    <SignupVisual />
                    <LoginForm />
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default Login;
